//! The emoji catalogue (D41): every fully-qualified emoji of UTS #51's
//! emoji-test.txt without a skin tone, in CLDR order, with its group and
//! CLDR short name (English), and the single-tone variants of those that
//! take a skin tone. Generated by gen.zig.

const std = @import("std");
const data = @import("emoji_data");
pub const names = @import("emoji_names.zig");

pub const version = data.version;
pub const count: u32 = data.emoji.len;
pub const group_count: u32 = names.groups.len;

/// Skin tones: 0 is none, 1 to 5 are U+1F3FB to U+1F3FF.
pub const Tone = u3;

/// The emoji's characters, with a skin tone if it takes one (otherwise
/// the tone is ignored).
pub fn sequence(index: u32, tone: Tone) []const u8 {
    const e = data.emoji[index];
    if (tone != 0 and e.tones != 0xffff) {
        const t = data.tones[e.tones][tone - 1];
        return data.pool[t[0]..][0..t[1]];
    }
    return data.pool[e.seq..][0..e.seq_len];
}

/// The emoji's CLDR short name, with the tone as `sequence` applies it;
/// `buf` holds a derived name.
pub fn name(buf: []u8, index: u32, tone: Tone) []const u8 {
    const e = data.emoji[index];
    const base = data.pool[e.name..][0..e.name_len];
    if (tone == 0 or e.tones == 0xffff) return base;
    const t = data.tones[e.tones][tone - 1];
    if (t[3] != 0) return data.pool[t[2]..][0..t[3]];
    return names.toned(buf, base, tone - 1);
}

pub fn group(index: u32) u8 {
    return data.emoji[index].group;
}

pub fn takesTone(index: u32) bool {
    return data.emoji[index].tones != 0xffff;
}

/// The index of a group's first emoji; `group_count` gives the end.
pub fn groupStart(g: u32) u32 {
    return if (g >= group_count) count else data.group_starts[g];
}

/// Whether every word of `query` starts a word of the emoji's name,
/// ignoring ASCII case: "smil cat" finds "grinning cat with smiling eyes".
pub fn matches(index: u32, query: []const u8) bool {
    const e = data.emoji[index];
    const n = data.pool[e.name..][0..e.name_len];
    var words = std.mem.tokenizeAny(u8, query, " \t:,");
    var any = false;
    while (words.next()) |q| {
        any = true;
        var found = false;
        var i: usize = 0;
        while (i + q.len <= n.len) : (i += 1) {
            if (i > 0 and std.ascii.isAlphanumeric(n[i - 1])) continue;
            if (std.ascii.eqlIgnoreCase(n[i..][0..q.len], q)) {
                found = true;
                break;
            }
        }
        if (!found) return false;
    }
    return any;
}

const testing = std.testing;

test "the catalogue: order, groups, tones, names" {
    try testing.expectEqualStrings("😀", sequence(0, 0));
    try testing.expectEqualStrings("grinning face", name(&.{}, 0, 0));
    try testing.expectEqual(@as(u8, 0), group(0));
    // Groups follow each other in CLDR order.
    var g: u32 = 0;
    while (g < group_count) : (g += 1) {
        try testing.expect(groupStart(g) < groupStart(g + 1));
        try testing.expectEqual(@as(u8, @intCast(g)), group(groupStart(g)));
    }
    var i: u32 = 0;
    var thumbs: ?u32 = null;
    var kiss: ?u32 = null;
    while (i < count) : (i += 1) {
        if (std.mem.eql(u8, name(&.{}, i, 0), "thumbs up")) thumbs = i;
        if (std.mem.eql(u8, name(&.{}, i, 0), "kiss: woman, man")) kiss = i;
    }
    var buf: [128]u8 = undefined;
    try testing.expect(takesTone(thumbs.?));
    try testing.expectEqualStrings("👍🏽", sequence(thumbs.?, 3));
    try testing.expectEqualStrings("thumbs up: medium skin tone", name(&buf, thumbs.?, 3));
    // CLDR puts the tone last in some names, which the catalogue keeps.
    try testing.expectEqualStrings("kiss: woman, man, light skin tone", name(&buf, kiss.?, 1));
    // Emoji without tones ignore them.
    try testing.expect(!takesTone(0));
    try testing.expectEqualStrings("😀", sequence(0, 5));
}

test "search by words of the name" {
    try testing.expect(matches(0, "grin"));
    try testing.expect(matches(0, "FACE grinning"));
    try testing.expect(!matches(0, "inning"));
    try testing.expect(!matches(0, ""));
    try testing.expect(!matches(0, "cat"));
}
